/bin/bash -lc "menv python - <<'PY'
from hera.analysis import *
import inspect
print(inspect.signature(sdh_fft)); print(inspect.getdoc(sdh_fft))
for i in (5,6,7):
 r=open_run(f'data/{i}'); print(summarize_run(r)); print(r.cols)
 print({k:r.meta[k] for k in ('start_time','end_time','delay','fast_delay','slow_delay','measurement_config') if k in r.meta})
 if i>5:
  B=r.col('magnet_field'); R=r.col('sr1_X')/(r.col('sr0_X')/-1e6)
  print('R range',R.min(),R.max(),'dt median',np.median(np.diff(r.col('time'))))
  try: print(sdh_onset(R,B,r_full_scale=2000 if i==6 else 5000).summary())
  except Exception as e: print(type(e).__name__,str(e))
PY"

